 if(funded&&(!selected||query.getAll('s2ServiceFixture').length!==1||query.get('s2ServiceFixture')!=='post-approved'||query.getAll('jangmokServices').length!==1||query.has('fixture')))throw Error('EXACT_FUNDED_QA_QUERY_REQUIRED');
 if(selected&&!funded&&(query.getAll('jangmokServices').length!==1||query.getAll('fixture').length!==1||query.get('fixture')!=='jangmok'))throw Error('EXPLICIT_NO_STORAGE_SERVICE_FIXTURE_REQUIRED');
 if(!selected)return startCanonicalWorld({developmentFixture:query.get('fixture')==='jangmok'?createJangmokReviewFixture:null,developmentReview:options=>installNativeReviewHost({...options,loadController:loadNativeReview})});
 let currentWorld=null,currentAdapter=null,disposed=false,lifecycle=null;const fixtureAbort=new AbortController();
