 const cleanups=new Set();const cleanup=e=>{if(e?.persisted)return;disposed=true;fixtureAbort.abort();currentAdapter=null;currentWorld=null;lifecycle?.dispose();healBinding.dispose();shopBinding.dispose();for(const release of cleanups)release();cleanups.clear();window.removeEventListener('pagehide',cleanup);};window.addEventListener('pagehide',cleanup);
 const loadVisuals=async()=>{let closed=false;const images=new Set(),release=()=>{closed=true;for(const im of images)im.close?.();images.clear();cleanups.delete(release);};cleanups.add(release);try{const value=await loadCenterVisuals({read:async u=>{const r=await fetch(u);if(!r.ok)throw Error('CENTER_ART_LOAD_FAILED');return new Uint8Array(await r.arrayBuffer());},decode:async b=>{const im=await createImageBitmap(new Blob([b]));if(disposed||closed){im.close?.();throw Error('CENTER_VISUAL_LOAD_CANCELLED');}images.add(im);return im;}});if(disposed||closed)throw Error('CENTER_VISUAL_LOAD_CANCELLED');return {...value,dispose:release};}catch(e){release();throw e;}};
